-- Schema drift closure, RLS policies part 1: the private schema (26 policies).
--
-- Policy DDL generated by the database from pg_policy via
-- scripts/generate-schema-ddl.sql, then md5-verified against that generated
-- text.
--
-- What this layer expresses: with two exceptions, every private-schema policy
-- is a deny. The private schema is reached only through SECURITY DEFINER
-- functions owned by postgres, which are exempt from RLS, and through
-- service_role, which carries rolbypassrls. Client roles are told "no" at the
-- table level so that a future accidental GRANT cannot turn into a data leak.
--
-- The distinction between the two deny styles is deliberate and worth keeping:
-- RESTRICTIVE policies (audit_log, brand_secrets, producer_application_kyc,
-- producer_documents, payment_events, idempotency_keys and others) cannot be
-- widened by adding a permissive policy later. Someone adding a well-meaning
-- "allow the owner to read their own row" policy to one of those tables would
-- still be denied, because a restrictive policy is ANDed with everything else.
-- On the most sensitive tables - KYC ciphertext, brand secrets, the audit
-- trail - that is the correct posture.
--
-- The one genuine grant here is user_roles_read_own, which lets a signed-in
-- user read their own unexpired roles and nothing else. It exists because the
-- client needs to know what the current user may do; it is scoped to
-- auth.uid() and filters expired grants.
--
-- Applying is a no-op against the live project: these policies already exist.
-- DROP POLICY IF EXISTS precedes each CREATE so the file is replayable.

DROP POLICY IF EXISTS admin_audit_logs_no_direct_client_access ON private.admin_audit_logs;
CREATE POLICY admin_audit_logs_no_direct_client_access ON private.admin_audit_logs
  FOR ALL
  TO anon, authenticated
  USING (false)
  WITH CHECK (false);

DROP POLICY IF EXISTS audit_log_deny_client_access ON private.audit_log;
CREATE POLICY audit_log_deny_client_access ON private.audit_log
  AS RESTRICTIVE
  FOR ALL
  TO anon, authenticated
  USING (false)
  WITH CHECK (false);

