DROP POLICY IF EXISTS user_roles_read_own ON private.user_roles;
CREATE POLICY user_roles_read_own ON private.user_roles
  FOR SELECT
  TO authenticated
  USING (((user_id = ( SELECT auth.uid() AS uid)) AND ((expires_at IS NULL) OR (expires_at > timezone('utc'::text, now())))));

